from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI()

class Invoice(BaseModel):
    amount: float = Field(ge=0)
    days_overdue: int = Field(ge=0)


def risk_rule(days_overdue: int) -> bool:
    return days_overdue >= 30

@app.get('/health')
def health():
    return {'status': 'ok'}

@app.post('/score')
def score(invoice: Invoice):
    return {'risk_flag': risk_rule(invoice.days_overdue), 'kind': 'rule_only'}

from fastapi.testclient import TestClient
from main import app

client = TestClient(app)

def test_health():
    r = client.get('/health')
    assert r.status_code == 200 and r.json() == {'status': 'ok'}

def test_score():
    r = client.post('/score', json={'amount': 200, 'days_overdue': 45})
    assert r.status_code == 200 and r.json()['risk_flag'] is True

def test_invalid():
    r = client.post('/score', json={'amount': -1, 'days_overdue': 45})
    assert r.status_code == 422
